 select DISTINCT m.EXTRACTION_DATE ,m.CUSTOMER_NUMBER ,m.LEGAL_IDNO , 
COALESCE(e.EXPOSURE_PRINCIPAL_BALANCE,0) as EXPOSURE_PRINCIPAL_BALANCE,  
COALESCE(ac.Total_ACC_Balances,0)as Total_ACC_Balances,
CASE 
	when COALESCE(e.EXPOSURE_PRINCIPAL_BALANCE,0)>0 then 'WITH EXPOSURE'
	ELSE 'NO EXPOSURE'
END EXPOSURE_STATUS,
CASE 
    WHEN ac.customer IS NULL THEN 'NO ACCOUNT'
    ELSE 'WITH ACCOUNT'
END AS ACCOUNT_STATUS
from
dbcba.KE_Customer_Master m
left join 
		(select  CUSTOMER ,(SUM(ONLINE_ACTUAL_BAL)*-1) AS EXPOSURE_PRINCIPAL_BALANCE
		from
		dbcba.KE_Accounts_List 
		where PRODUCT_LINE ='LENDING' AND ONLINE_ACTUAL_BAL IS NOT NULL
		GROUP BY CUSTOMER ) e 
on
		m.CUSTOMER_NUMBER =e.customer 
left join  (select CUSTOMER,SUM(ONLINE_ACTUAL_BAL) AS Total_ACC_Balances from dbcba.KE_Accounts_List 
			where  PRODUCT_LINE ='ACCOUNTS' AND ONLINE_ACTUAL_BAL IS NOT NULL
			GROUP BY CUSTOMER) ac
			on m.CUSTOMER_NUMBER =ac.customer 
where m.EXTRACTION_DATE =(select max(processing_date) from dbcba.end_of_day) --and CUSTOMER_NUMBER ='233538'
and LEGAL_IDNO in 
